v1SourceSnips.relEntryTitle:
function relEntryTitle(dim, it) {
        if (!it) return '';
        const t = String(it.title || '').trim();
        const c = String(it.content || it.text || '').trim();
        const s = (t && c && t !== c) ? `${t}：${c}` : (t || c);
        return s.length > 60 ? s.slice(0, 59) + '…' : s;
    }

v1SourceSnips.relFindEntryId:
function relFindEntryId(dim, raw) {
        try {
            const list = (state && state[dim]) || [];
            const id0 = String((raw && raw.id) || '');
            if (id0 && list.some(x => x && String(x.id) === id0)) return id0;
            const content = String((raw && (raw.content || raw.text)) || '').trim();
            const title = String((raw && (raw.title || raw.name)) || '').trim();
            if (!content && !title) return '';
            const hit = list.slice().reverse().find(x => x
                && (!content || String(x.content || '').trim() === content)
                && (!title || String(x.title || '').trim() === title));
            return hit ? String(hit.id) : '';
        } catch (e) { return ''; }
    }

v1SourceSnips.relKnownNames:
function relKnownNames() {
        const out = [];
        const push = (nm) => {
            const t = String(nm == null ? '' : nm).trim();
            if (t && out.indexOf(t) < 0) out.push(t);
        };
        try { for (const s of ((state && state.snapshots) || [])) push(s && s.name); } catch (e) { }
        try { if (typeof knownCharacterNames === 'function') for (const nm of knownCharacterNames()) push(nm); } catch (e) { }
        return out;
    }

v1SourceSnips.relPickAppendRow:
function relPickAppendRow(box, dim, name) {
        try {
            if (!box || !box.insertAdjacentHTML) return false;
            const who = String(name == null ? '' : name).trim();
            if (!who || !relIsRelDim(dim)) return false;
            let dup = false;
            try {
                const trs = box.querySelectorAll ? box.querySelectorAll('[data-ftt-rel-row]') : [];
                for (const tr of trs) {
                    if (!tr || !tr.getAttribute) continue;
                    if (String(tr.getAttribute('data-ftt-rel-anchor') || '') === '1') continue;
                    const el = tr.querySelector ? tr.querySelector('[data-ftt-relf="who"]') : null;
                    if (el && typeof snapNameKey === 'function' && snapNameKey(String(el.value || '')) === snapNameKey(who)) { dup = true; break; }
                    if (el && String(el.value || '').trim() === who) { dup = true; break; }
                }
            } catch (e) { }
            if (dup) return 'dup';
            box.insertAdjacentHTML('beforeend', relRowHtml(dim, { who, how: String(dim) === 'parallels' ? 'related' : 'unspecified' }));
            return true;
        } catch (e) { return false; }
    }

