        let linked = [];
        try { linked = (relIsRelDim(dim) && refId && !editor) ? relLinksOf(dim, refId).filter(x => x.who).map(x => String(x.who)) : []; } catch (e) { linked = []; }
        const isOn = (nm) => linked.some(w => (typeof snapNameKey === 'function' ? snapNameKey(w) === snapNameKey(nm) : w === nm));
        pageListRenderers['relPick'] = () => {
            const shown = pageSearchItems('relPick', names.map(nm => ({ name: nm })));
            pageListCounts['relPick'] = { shown: shown.length, total: names.length };
            if (!names.length) return '<div class="ftt-empty">「角色」大类暂无已知角色：先运行「AI 摘要」生成角色档案，或在角色页添加角色。</div>';
            if (!shown.length) return `<div class="ftt-empty">无匹配角色（搜索：${escHtml(pageSearchQuery['relPick'] || '')}）</div>`;
            return shown.map(x => {
                const on = isOn(x.name);
                return `<div class="ftt-item" ${rowAttrs('relPick', { name: x.name })}><div class="ftt-item-main"><b>${escHtml(x.name)}</b>${on ? ' <span class="ftt-badge ftt-badge--fact">已在关联</span>' : ''}</div>`
                    + `<div class="ftt-item-ops"><button class="ftt-op${on ? ' ftt-ok' : ''}" data-ftt-action="relPickAdd" data-ftt-kind="${escHtml(dim)}" data-ftt-id="${escHtml(String(refId == null ? '' : refId))}" data-ftt-editor="${editor ? '1' : ''}" data-ftt-name="${escHtml(x.name)}" title="添加为该条目的关联角色（点「保存关联」落库）">➕</button></div></div>`;
            }).join('\n');
        };
        const body = pageListRenderers['relPick']();
        const label = editor ? `${relDimLabelOf(dim)}（编辑器）` : relDimLabelOf(dim);
        return `<div class="ftt-editor" data-ftt-rel-pick="${escHtml(relPickKey(dim, refId, editor))}">`
            + `<div class="ftt-editor-title">👥 选角色 · 加到「${escHtml(label)}」的关联（角色档案 ${names.length} 名）</div>`
            + `<div class="ftt-muted ftt-w-full">只从<b>角色档案</b>点名，不遍历记忆 / 计划 / 悬念 / 平行条目；点 ➕ 追加一行角色，仍要点「💾 保存关联」才落库。</div>`
            + searchBoxHtml('relPick', '搜索角色名…', names.length, names.length)
            + `<div data-ftt-list="relPick">${body}</div>`
            + `<div class="ftt-row"><button class="ftt-btn" data-ftt-action="relPickClose">关闭</button></div></div>`;
    }
